describe('isValidEmail', () => {
  test('should accept valid email', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
  });
  test('should reject email without @', () => {
    expect(isValidEmail('userexample.com')).toBe(false);
  });
  test('should reject email without domain', () => {
    expect(isValidEmail('user@')).toBe(false);
  });
  test('should reject email without TLD', () => {
    expect(isValidEmail('user@example')).toBe(false);
  });
  test('should reject email with spaces', () => {
    expect(isValidEmail('user @example.com')).toBe(false);
  });
  test('should reject multiple @ symbols', () => {
    expect(isValidEmail('user@@example.com')).toBe(false);
  });
});

describe('sanitizeInput', () => {
  test('should escape < character', () => {
    expect(sanitizeInput('<script>')).toBe('&lt;script&gt;');
  });
  test('should escape > character', () => {
    expect(sanitizeInput('</div>')).toBe('&lt;/div&gt;');
  });
  test('should escape double quotes', () => {
    expect(sanitizeInput('"quoted"')).toBe('&quot;quoted&quot;');
  });
  test('should escape single quotes', () => {
    expect(sanitizeInput("'quoted'")).toBe('&#039;quoted&#039;');
  });
  test('should escape all special characters together', () => {
    expect(sanitizeInput('<img src="x" onerror="alert(\'XSS\')"/>')).toBe('&lt;img src=&quot;x&quot; onerror=&quot;alert(&#039;XSS&#039;)&quot;/&gt;');
  });
  test('should handle empty string', () => {
    expect(sanitizeInput('')).toBe('');
  });
});

describe('createUser', () => {
  test('should create user with valid input', async () => {
    const result = await createUser({ email: 'test@example.com', name: 'John Doe' });
    expect(result).toMatchObject({
      email: 'test@example.com',
      name: 'John Doe'
    });
    expect(result.id).toBeDefined();
    expect(result.createdAt).toBeInstanceOf(Date);
  });
  test('should lowercase email', async () => {
    const result = await createUser({ email: 'TEST@EXAMPLE.COM', name: 'John' });
    expect(result.email).toBe('test@example.com');
  });
  test('should sanitize name with special characters', async () => {
    const result = await createUser({ email: 'test@example.com', name: '<script>alert("xss")</script>' });
    expect(result.name).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
  });
});

